OUTPUT_FILENAME = "entry.png"


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    # Validate the embedded payload is a real PNG before writing anything.
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("embedded image data is not a valid PNG")
    if len(data) > 1_048_576:
        raise ValueError(f"embedded PNG exceeds 1 MiB ({len(data)} bytes)")
    out_path = os.path.join(out_dir, OUTPUT_FILENAME)
    with open(out_path, "wb") as f:
        f.write(data)
    print(f"Wrote {out_path} ({len(data)} bytes)")


if __name__ == "__main__":
    main()
